// Generates the TypeScript and Go code of proto/ with the plugin versions this repository pins:
// protoc-gen-es from the pnpm catalog and protoc-gen-go from helpers/tailnet/go.mod. The Rust code
// is generated by helpers/device/build.rs. Run with `pnpm proto:generate`.
import * as NodeRuntime from "@effect/platform-node/NodeRuntime";
import * as NodeServices from "@effect/platform-node/NodeServices";
import * as Effect from "effect/Effect";
import * as Path from "effect/Path";

import { runInherited } from "./lib/run.ts";

const program = Effect.gen(function* () {
  const path = yield* Path.Path;
  const root = path.resolve(import.meta.dirname, "..");

  yield* runInherited(
    "go",
    [
      "-C",
      "helpers/tailnet",
      "build",
      "-o",
      path.join(root, ".cache", "bin", "protoc-gen-go"),
      "google.golang.org/protobuf/cmd/protoc-gen-go",
    ],
    root,
  );
  yield* runInherited(path.join(root, "node_modules", ".bin", "buf"), ["generate"], root);
});

NodeRuntime.runMain(program.pipe(Effect.provide(NodeServices.layer)));
